create table readings (id bigint generated always as identity primary key, org_id integer not null, kind text not null, taken_at timestamptz not null, watts integer not null, cost numeric(10,2) not null, peak integer);
create index on readings (taken_at);
create index on readings (org_id, kind);
insert into readings (org_id, kind, taken_at, watts, cost, peak)
  select 1 + i % 2, case when i % 3 = 0 then 'heat' else 'power' end, timestamptz '2026-07-01 00:00:00+00' + i * interval '263 seconds',
    i % 500, (i % 1000) / 100.0, case when i % 7 > 0 then i % 90 end
  from generate_series(1, 3000) as i;

create schema if not exists "rollups";

create table "public"."readings_hourly" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "kind" text not null, "events" bigint not null, "watts_sum" bigint, "watts_max" integer, "cost_sum" numeric(20,2), "peak_sum" bigint);

create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id", "kind");

create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket");

create index "readings_hourly_kind_bucket" on "public"."readings_hourly" ("kind", "bucket");

comment on table "public"."readings_hourly" is 'protobase time rollup: create table "public"."readings_hourly" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "kind" text not null, "events" bigint not null, "watts_sum" bigint, "watts_max" integer, "cost_sum" numeric(20,2), "peak_sum" bigint); create unique index "readings_hourly_bucket_key" on "public"."readings_hourly" ("bucket", "org_id", "kind"); create index "readings_hourly_org_id_bucket" on "public"."readings_hourly" ("org_id", "bucket"); create index "readings_hourly_kind_bucket" on "public"."readings_hourly" ("kind", "bucket")';

create or replace function "rollups"."readings_hourly_refresh"("from" timestamptz) returns void language sql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
with fresh as (
  select date_trunc('hour', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", c."kind" as "kind", count(*) as "events", sum(c."watts") as "watts_sum", max(c."watts") as "watts_max", sum(c."cost") as "cost_sum", sum(c."peak") as "peak_sum"
  from public.readings as c
  where c."taken_at" >= date_trunc('hour', $1)
  group by 1, 2, 3
), gone as (
  delete from "public"."readings_hourly" as r where r."bucket" >= date_trunc('hour', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id" and fresh."kind" = r."kind")
)
insert into "public"."readings_hourly" ("bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum", "peak_sum")
select "bucket", "org_id", "kind", "events", "watts_sum", "watts_max", "cost_sum", "peak_sum" from fresh
on conflict ("bucket", "org_id", "kind") do update set "events" = excluded."events", "watts_sum" = excluded."watts_sum", "watts_max" = excluded."watts_max", "cost_sum" = excluded."cost_sum", "peak_sum" = excluded."peak_sum"
$buckets$;

select "rollups"."readings_hourly_refresh"('-infinity');

create table "public"."readings_daily" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "events" bigint not null, "watts_sum" bigint);

create unique index "readings_daily_bucket_key" on "public"."readings_daily" ("bucket", "org_id");

create index "readings_daily_org_id_bucket" on "public"."readings_daily" ("org_id", "bucket");

comment on table "public"."readings_daily" is 'protobase time rollup: create table "public"."readings_daily" ("id" bigint generated always as identity primary key, "bucket" timestamptz not null, "org_id" integer not null, "events" bigint not null, "watts_sum" bigint); create unique index "readings_daily_bucket_key" on "public"."readings_daily" ("bucket", "org_id"); create index "readings_daily_org_id_bucket" on "public"."readings_daily" ("org_id", "bucket")';

create or replace function "rollups"."readings_daily_refresh"("from" timestamptz) returns void language sql set search_path = pg_catalog, pg_temp set timezone = 'UTC' as $buckets$
with fresh as (
  select date_trunc('day', c."taken_at"::timestamptz) as "bucket", c."org_id" as "org_id", count(*) as "events", sum(c."watts") as "watts_sum"
  from public.readings as c
  where c."taken_at" >= date_trunc('day', $1)
  group by 1, 2
), gone as (
  delete from "public"."readings_daily" as r where r."bucket" >= date_trunc('day', $1) and not exists (select from fresh where fresh."bucket" = r."bucket" and fresh."org_id" = r."org_id")
)
insert into "public"."readings_daily" ("bucket", "org_id", "events", "watts_sum")
select "bucket", "org_id", "events", "watts_sum" from fresh
on conflict ("bucket", "org_id") do update set "events" = excluded."events", "watts_sum" = excluded."watts_sum"
$buckets$;

select "rollups"."readings_daily_refresh"('-infinity');
